'use strict';
const assert=require('assert');
const fs=require('fs');
const path=require('path');
const root=path.join(__dirname,'..');
const index=fs.readFileSync(path.join(root,'index.html'),'utf8');
const app=fs.readFileSync(path.join(root,'app.js'),'utf8');
const css=fs.readFileSync(path.join(root,'styles.css'),'utf8');
const sw=fs.readFileSync(path.join(root,'service-worker.js'),'utf8');
assert(index.includes('56.0.5-schedule-card-format1'),'HTML assets must use the v55.4.5 cache token');
assert(sw.includes('tuinbooks-shell-v56-0-5-schedule-card-format1'),'Service worker cache must be bumped');
assert(index.includes('id="billingTimingAlertV5545"'),'Billing must expose a timing-alert host');
assert(index.includes('id="settingPaymentTermsDays"'),'Settings must store numeric payment terms');
assert(index.includes('id="settingDefaultInvoiceTiming"'),'Settings must define default invoice timing');
assert(index.includes('id="clientServiceStartDate"'),'Client form must capture service start date');
assert(index.includes('id="clientFirstBillingRule"'),'Client form must capture the first-period rule');
assert(index.includes('Prorate by scheduled visits'),'Recommended first-period wording must be visible');
assert(app.includes('lateInvoiceRowsV5545'),'Late-to-invoice detection must exist');
assert(app.includes('paymentAgeV5545'),'Payment ageing counter must exist');
assert(app.includes('invoice.dueDate=dateAdd'),'Confirmed sends must calculate a due date');
assert(app.includes('maySendInvoiceEarlyV5545'),'Early sending must require confirmation');
assert(app.includes("firstBillingRule||'prorate_visits'"),'Proration must be the default first-period rule');
assert(app.includes("rule==='carry_next_month'"),'Carry-forward first periods must be supported');
assert(css.includes('.invoice-age-badge-v5545'),'Payment-age badges must be styled');
console.log('v55.4.5 billing timing tests passed');
